import { useState } from 'react';
import {
  Pressable,
  SafeAreaView,
  Platform,
  StatusBar,
  StyleSheet,
  Text,
  useColorScheme,
  View,
} from 'react-native';
// @generated by scripts/gen-registry.mjs (region: screen-imports) - do not edit; run bun run regen
import ButtonScreen from './ButtonScreen';
import DatePickerScreen from './DatePickerScreen';
import PickerScreen from './PickerScreen';
import ProgressScreen from './ProgressScreen';
import SegmentedControlScreen from './SegmentedControlScreen';
import SliderScreen from './SliderScreen';
import SwitchScreen from './SwitchScreen';
// @end-generated
// `Host` has no manifest (it is a container, not a control), so its screen is the
// one import the registry does not write.
import HostScreen from './HostScreen';
// T18's TextField spike (`docs/tasks/T18-textfield-spike.md`): a spike, so it has no manifest and the
// registry writes no row for it. Delete this import, the `'spike'` screen, its tab and its body line with
// `src/spike/`.
import SpikeTextFieldScreen from './SpikeTextFieldScreen';

type Screen =
  // @generated by scripts/gen-registry.mjs (region: screens) - do not edit; run bun run regen
  | 'switch'
  | 'slider'
  | 'button'
  | 'progress'
  | 'segmented'
  | 'datepicker'
  | 'picker'
  // @end-generated
  // The shared-composition screen, which is not a control and has no manifest.
  | 'host'
  // T18's spike screen: same reason as `host` — no manifest, so no generated row.
  | 'spike';

/**
 * Which screen a cold launch shows.
 *
 * A constant rather than a build-time variable: Metro only inlines `NODE_ENV`
 * here, so an `process.env`-based switch would need a Metro config for one
 * developer convenience. Task screenshots are taken with this flipped (see the
 * task report), which needs no Metro change and no rebuild of anything else.
 *
 * Keep the committed value a screen the window can go idle on, and land it back
 * here after a screenshot session. The Progress screen draws two indeterminate
 * indicators and starts its 60 Hz writer on mount, so on Android that window
 * never idles: `uiautomator dump` answers "could not get idle state", and
 * `bun run test:real-input:android` - which reads the screen that way - then
 * never sees the tab bar and times out (A2 measured it: the same timeout on
 * `main` and on this branch, and a dump that succeeds one tab over).
 */
const DEFAULT_SCREEN: Screen = 'switch';

/**
 * The tab bar's top padding.
 *
 * RN's `SafeAreaView` is iOS-only, and Android lays apps out edge to edge, so on
 * Android the tabs drew under the clock - the round-1 review's screenshots.
 * `StatusBar.currentHeight` is core's answer for that inset on Android and `null`
 * on iOS, where `SafeAreaView` is already doing the work, so this covers both
 * without taking `react-native-safe-area-context` into the example for one tab
 * bar. A display cutout taller than the status bar would still overlap; the
 * example is not where to solve that.
 */
const topInset =
  (Platform.select({ android: StatusBar.currentHeight, default: 0 }) ?? 0) + 4;

const TABS: { id: Screen; label: string }[] = [
  // @generated by scripts/gen-registry.mjs (region: tabs) - do not edit; run bun run regen
  { id: 'switch', label: 'Switch' },
  { id: 'slider', label: 'Slider' },
  { id: 'button', label: 'Button' },
  { id: 'progress', label: 'Progress' },
  { id: 'segmented', label: 'Segments' },
  { id: 'datepicker', label: 'Dates' },
  { id: 'picker', label: 'Picker' },
  // @end-generated
  // The shared-`<Host>` screen: real-input taps it (iOS included, where `Host` is the
  // passthrough) and `Host.harness.tsx` measures it. `Host` composes on Android only.
  { id: 'host', label: 'Host' },
  // T18's TextField spike, with its two real-input checks. Deleted with `src/spike/`.
  { id: 'spike', label: 'Spike' },
];

/**
 * Playground for the library. T10 put the Switch tracer bullet here; G1 added
 * the Slider, G2 the Button and G3 the Progress; every task adds a screen.
 *
 * The tabs are the only navigation: the harness renders its own UI, and a
 * screenshot of the example app is a screenshot of whichever screen is showing.
 */
export default function App() {
  const [screen, setScreen] = useState<Screen>(DEFAULT_SCREEN);
  const dark = useColorScheme() === 'dark';

  return (
    <View style={[styles.root, dark ? null : styles.rootLight]}>
      <SafeAreaView style={[styles.tabs, dark ? null : styles.tabsLight]}>
        {TABS.map((tab) => (
          <Pressable
            key={tab.id}
            onPress={() => setScreen(tab.id)}
            testID={`tab-${tab.id}`}
            style={[
              styles.tab,
              screen === tab.id &&
                (dark ? styles.tabActive : styles.tabActiveLight),
            ]}
          >
            <Text
              numberOfLines={1}
              adjustsFontSizeToFit
              minimumFontScale={0.7}
              style={[
                styles.tabLabel,
                screen === tab.id && (dark ? styles.ink : styles.inkLight),
              ]}
            >
              {tab.label}
            </Text>
          </Pressable>
        ))}
      </SafeAreaView>
      <View style={styles.body}>
        {/* @generated by scripts/gen-registry.mjs (region: screens-body) - do not edit; run bun run regen */}
        {screen === 'switch' ? <SwitchScreen /> : null}
        {screen === 'slider' ? <SliderScreen /> : null}
        {screen === 'button' ? <ButtonScreen /> : null}
        {screen === 'progress' ? <ProgressScreen /> : null}
        {screen === 'segmented' ? <SegmentedControlScreen /> : null}
        {screen === 'datepicker' ? <DatePickerScreen /> : null}
        {screen === 'picker' ? <PickerScreen /> : null}
        {/* @end-generated */}
        {screen === 'host' ? <HostScreen /> : null}
        {screen === 'spike' ? <SpikeTextFieldScreen /> : null}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  root: {
    flex: 1,
    backgroundColor: '#000',
  },
  rootLight: {
    backgroundColor: '#fff',
  },
  tabs: {
    flexDirection: 'row',
    gap: 4,
    paddingHorizontal: 4,
    paddingBottom: 4,
    paddingTop: topInset,
    backgroundColor: '#111',
  },
  tabsLight: {
    backgroundColor: '#ececec',
  },
  /**
   * Seven intrinsic-width tabs do not fit a 420 pt window: with G5's Dates tab
   * and this task's Picker tab both appended, the Picker tab drew from x 434 and
   * was wholly outside the window, so a real tap on it could never land (the
   * iOS real-input check measured it). Sharing the row equally keeps every tab on
   * screen, and the row exactly one line tall - a second row costs the body 32 pt
   * of height, which is enough to flip where UIKit anchors a `DatePicker` popover
   * and break G5's anchoring check. The label shrinks to fit instead.
   */
  tab: {
    flex: 1,
    alignItems: 'center',
    paddingVertical: 6,
    borderRadius: 6,
  },
  tabActive: {
    backgroundColor: '#333',
  },
  tabActiveLight: {
    backgroundColor: '#d5d5d8',
  },
  tabLabel: {
    color: '#9d9da2',
    fontSize: 13,
  },
  ink: {
    color: '#fff',
  },
  inkLight: {
    color: '#000',
  },
  body: {
    flex: 1,
  },
});
